    def serialize(cls, a: AgentModel) -> AgentResponse:
        return AgentResponse(
            id=a.id,
            name=a.name,
            license_code=a.license_code,
            active=a.active,
            created_at=a.created_at.isoformat(),
            updated_at=a.updated_at.isoformat(),
        )

